let marks = 72;

if (marks >= 90) {
  console.log('A');
} else if (marks >= 75) {
  console.log('B');
} else if (marks >= 60) {
  console.log('C');
} else {
  console.log('D');
}

switch (true) {
  case marks >= 90:
    console.log('A');
    break;
  case marks >= 75:
    console.log('B');
    break;
  case marks >= 60:
    console.log('C');
    break;
  default:
    console.log('D');
}

let sum = 0;
for (let i = 1; i <= 5; i++) {
  sum += i;
}
console.log(sum);
